const ticket = $('Create Support Ticket in Postgres').first().json;
const ticketNumber = ticket.ticket_number || 'TICK-NEW';

return [{
  json: {
    status: 'escalated',
    intent_handled: 'human_escalation',
    ticket_number: ticketNumber,
    priority: ticket.priority,
    reply: `I understand this requires human assistance. I have opened priority support ticket #${ticketNumber} for you. A specialist has been assigned and is reviewing your request.`
  }
}];
